import { toHex } from '@exodus/bytes/hex.js'

// Only to be ever used on underlying implementations outputs, as it uses a no-copy conversion where possible

const outputFormats = new Set(['hex', 'buffer', 'uint8'])

export function assertOutputFormat(form) {
  if (!outputFormats.has(form)) throw new TypeError('Unsupported output format')
}

// From Uint8Array or a Buffer, defaults to uint8
export function fromUint8Super(arr, form = 'uint8') {
  assertOutputFormat(form)
  if (!(arr instanceof Uint8Array)) throw new Error('Unreachable')
  switch (form) {
    case 'uint8':
      if (arr.constructor === Uint8Array) return arr // fast path
      return new Uint8Array(arr.buffer, arr.byteOffset, arr.byteLength)
    case 'buffer':
      if (arr.constructor === Buffer && Buffer.isBuffer(arr)) return arr
      return Buffer.from(arr.buffer, arr.byteOffset, arr.byteLength)
    case 'hex':
      return toHex(arr)
  }
  throw new Error('Unreachable')
}
